#!/bin/bash
# ============================================================
# update45.sh
# 【資料遺失事故修復】log/CDR rotate 的 truncate 從未搭配 SIGHUP，
# 導致 FreeSwitch 既有 fd 的寫入 offset 從未重置，新內容實質上寫不進
# freeswitch.log / Master.csv。已確認影響範圍：
#   - freeswitch.log：至少自 2026-07-06 起（fd 開檔時間）持續中
#   - CDR：2026-07-04~07-19、07-21~08-11 共約 5 週幾乎完全遺失
#     （僅 07-03、07-20 各捕捉到個位數筆數，推測當天 fd 意外被重置過）
# 對應：changelog-details/20260811-log-rotate-hup-fix.md
#
# 修改檔案：core/runtime.py（整份覆寫）、routers/logs.py、routers/cdr.py
# （後兩者為精確字串替換）
# ============================================================
set -e

cd "$(dirname "$0")"

# --- 0. 自動歸檔：把非本次腳本的其他 updateN.sh 搬進固定資料夾 ---
ARCHIVE_DIR="updateN"
SELF="$(basename "$0")"

mkdir -p "$ARCHIVE_DIR"
for f in update*.sh; do
  [ "$f" = "$SELF" ] && continue
  [ -f "$f" ] || continue
  git mv "$f" "${ARCHIVE_DIR}/$f" 2>/dev/null || mv "$f" "${ARCHIVE_DIR}/$f"
done
git add update*.sh "$ARCHIVE_DIR"/ 2>/dev/null || true
if ! git diff --cached --quiet 2>/dev/null; then
  git commit -m "chore: 歸檔已執行的 updateN.sh 腳本"
fi

# --- 1. 前置驗證 ---
echo "[前置驗證] 確認三個目標檔案目前內容符合預期（尚未套用本次改動）..."

for f in core/runtime.py routers/logs.py routers/cdr.py; do
  if [ ! -f "$f" ]; then
    echo "❌ 找不到 $f" >&2
    exit 1
  fi
done

if grep -q "_rotate_log_and_cdr_now" core/runtime.py; then
  echo "❌ core/runtime.py 已包含 _rotate_log_and_cdr_now，本次改動可能已套用過，中止避免重複套用" >&2
  exit 1
fi

if ! grep -q 'def _rotate_log_now' core/runtime.py; then
  echo "❌ core/runtime.py 內容與預期不符（找不到 _rotate_log_now 定義），請先確認檔案目前實際內容" >&2
  exit 1
fi

if ! grep -q "_rotate_log_now" routers/logs.py; then
  echo "❌ routers/logs.py 內容與預期不符（找不到 _rotate_log_now import），請先確認檔案目前實際內容" >&2
  exit 1
fi

if ! grep -q "_rotate_cdr_now" routers/cdr.py; then
  echo "❌ routers/cdr.py 內容與預期不符（找不到 _rotate_cdr_now import），請先確認檔案目前實際內容" >&2
  exit 1
fi

echo "  ✓ 前置驗證通過"

# --- 2. core/runtime.py：整份覆寫（base64 還原，避免 SSH heredoc 貼上內容被截斷/打亂）---
echo "[Step 1] 覆寫 core/runtime.py..."
cp core/runtime.py core/runtime.py.pre-update45.bak

echo "" | base64 -d > core/runtime.py

if [ ! -s core/runtime.py ]; then
  echo "❌ core/runtime.py 覆寫後為空檔案，還原備份並中止" >&2
  cp core/runtime.py.pre-update45.bak core/runtime.py
  exit 1
fi

# --- 3. routers/logs.py：精確字串替換 ---
echo "[Step 2] 套用 routers/logs.py 改動..."
cp routers/logs.py routers/logs.py.pre-update45.bak

python3 << 'PYEOF_LOGS'
import sys

path = "routers/logs.py"
with open(path, "r", encoding="utf-8") as f:
    content = f.read()

edits = []

old1 = 'from core.runtime import FS_LOG_DIR, FS_LOG_FILE, _rotate_log_now'
new1 = 'from core.runtime import FS_LOG_DIR, FS_LOG_FILE, _rotate_log_and_cdr_now'
edits.append(("import", old1, new1))

old2 = '''@router.post("/api/logs/rotate", dependencies=[Depends(require_permission(Module.LOGS, "update"))])
def rotate_log_now():
    """手動立即執行 log 輪轉（將今天以前的 log 另存為日期檔）"""
    result = _rotate_log_now()
    if not result["ok"]:
        raise HTTPException(status_code=400, detail=result["error"])
    return result'''

new2 = '''@router.post("/api/logs/rotate", dependencies=[Depends(require_permission(Module.LOGS, "update"))])
def rotate_log_now():
    """
    手動立即執行 log 輪轉（將今天以前的 log 另存為日期檔）。

    2026-08-11 起改呼叫 `_rotate_log_and_cdr_now()`：SIGHUP 是 FreeSwitch
    process 層級訊號，重新開啟 log 檔案的同時也會讓 mod_cdr_csv 反應，
    若不同時安全歸檔 CDR，Master.csv 裡尚未保存的內容會被 FreeSwitch
    自己的 rotate-on-hup 邏輯搬進孤兒檔案。因此點擊「立即輪轉」會連帶
    把今天累積的 CDR 一併歸檔（等同同時按了 CDR 頁面的「立即歸檔」），
    這是刻意的行為變更，避免資料遺失。詳見
    changelog-details/20260811-log-rotate-hup-fix.md。
    """
    result = _rotate_log_and_cdr_now(cdr_use_today=True, primary="log")
    if not result["ok"]:
        raise HTTPException(status_code=400, detail=result["error"])
    return result'''

edits.append(("rotate_log_now", old2, new2))

for name, old, new in edits:
    count = content.count(old)
    if count != 1:
        print(f"❌ 比對錨點「{name}」在 routers/logs.py 中出現 {count} 次（預期 1 次），中止", file=sys.stderr)
        sys.exit(1)
    content = content.replace(old, new)

with open(path, "w", encoding="utf-8") as f:
    f.write(content)

print("  ✓ routers/logs.py 兩處改動皆已套用")
PYEOF_LOGS

if [ $? -ne 0 ]; then
  echo "❌ routers/logs.py 字串替換失敗，還原備份並中止" >&2
  cp routers/logs.py.pre-update45.bak routers/logs.py
  cp core/runtime.py.pre-update45.bak core/runtime.py
  exit 1
fi

# --- 4. routers/cdr.py：精確字串替換 ---
echo "[Step 3] 套用 routers/cdr.py 改動..."
cp routers/cdr.py routers/cdr.py.pre-update45.bak

python3 << 'PYEOF_CDR'
import sys

path = "routers/cdr.py"
with open(path, "r", encoding="utf-8") as f:
    content = f.read()

edits = []

old1 = 'from core.runtime import CDR_DIR, CDR_MASTER, _rotate_cdr_now'
new1 = 'from core.runtime import CDR_DIR, CDR_MASTER, _rotate_log_and_cdr_now'
edits.append(("import", old1, new1))

old2 = '''@router.post("/api/cdr/rotate", dependencies=[Depends(require_permission(Module.CDR, "update"))])
def rotate_cdr_now():
    """手動立即執行 CDR 歸檔（用今天日期）：同步進 DB → 建彙總 → 封存 CSV → 清空 Master.csv"""
    result = _rotate_cdr_now(use_today=True)
    if not result["ok"]:
        raise HTTPException(status_code=400, detail=result["error"])
    return result'''

new2 = '''@router.post("/api/cdr/rotate", dependencies=[Depends(require_permission(Module.CDR, "update"))])
def rotate_cdr_now():
    """
    手動立即執行 CDR 歸檔（用今天日期）：同步進 DB → 建彙總 → 封存 CSV → 清空 Master.csv。

    2026-08-11 起改呼叫 `_rotate_log_and_cdr_now()`：SIGHUP 是 FreeSwitch
    process 層級訊號，重新開啟 CDR 檔案的同時也會讓 mod_logfile 反應，
    若不同時安全歸檔 log，freeswitch.log 裡尚未保存的內容會被 FreeSwitch
    自己的 rotate-on-hup 邏輯搬進孤兒檔案。因此點擊「立即歸檔」會連帶把
    log 一併輪轉（等同同時按了系統日誌頁面的「立即輪轉」），這是刻意的
    行為變更，避免資料遺失。詳見
    changelog-details/20260811-log-rotate-hup-fix.md。
    """
    result = _rotate_log_and_cdr_now(cdr_use_today=True, primary="cdr")
    if not result["ok"]:
        raise HTTPException(status_code=400, detail=result["error"])
    return result'''

edits.append(("rotate_cdr_now", old2, new2))

for name, old, new in edits:
    count = content.count(old)
    if count != 1:
        print(f"❌ 比對錨點「{name}」在 routers/cdr.py 中出現 {count} 次（預期 1 次），中止", file=sys.stderr)
        sys.exit(1)
    content = content.replace(old, new)

with open(path, "w", encoding="utf-8") as f:
    f.write(content)

print("  ✓ routers/cdr.py 兩處改動皆已套用")
PYEOF_CDR

if [ $? -ne 0 ]; then
  echo "❌ routers/cdr.py 字串替換失敗，還原全部備份並中止" >&2
  cp routers/cdr.py.pre-update45.bak routers/cdr.py
  cp routers/logs.py.pre-update45.bak routers/logs.py
  cp core/runtime.py.pre-update45.bak core/runtime.py
  exit 1
fi

# --- 5. 語法驗證（三個檔案都要過）---
echo "[Step 4] Python 語法檢查..."
PY=python3
command -v /opt/myapp/venv/bin/python3 >/dev/null 2>&1 && PY=/opt/myapp/venv/bin/python3

for f in core/runtime.py routers/logs.py routers/cdr.py; do
  $PY -c "import ast; ast.parse(open('$f').read())" \
    && echo "  ✓ $f 語法檢查通過" \
    || {
      echo "❌ $f 語法檢查失敗，還原全部備份" >&2
      cp routers/cdr.py.pre-update45.bak routers/cdr.py
      cp routers/logs.py.pre-update45.bak routers/logs.py
      cp core/runtime.py.pre-update45.bak core/runtime.py
      exit 1
    }
done

# --- 6. 清掉備份檔（確認語法都過了才清）---
rm -f core/runtime.py.pre-update45.bak routers/logs.py.pre-update45.bak routers/cdr.py.pre-update45.bak

# --- 7. git commit ---
echo "[Step 5] git commit..."
git add core/runtime.py routers/logs.py routers/cdr.py
git status
git commit -m "fix: log/CDR rotate 補送 SIGHUP，修復持續資料遺失事故（truncate 未搭配訊號導致 FreeSwitch fd offset 從未重置）"

echo ""
echo "======================================================"
echo " ✓ update45.sh 執行完成"
echo ""
git log --oneline -1
echo ""
echo " ⚠️ 本次修改 core/runtime.py、routers/logs.py、routers/cdr.py，"
echo "    依慣例需要重啟服務讓改動生效："
echo "    systemctl restart fs-dashboard"
echo ""
echo " 驗證重點清單："
echo "  1. systemctl restart fs-dashboard 後 systemctl status fs-dashboard 確認正常啟動、無 500"
echo "  2. 立刻測試修復是否生效（在 Dashboard 系統日誌頁面按「立即輪轉」，或 CDR 頁面按「立即歸檔」，兩者現在效果相同）"
echo "  3. 確認 fd offset 真的被重置："
echo "     FS_PID=\$(pgrep -f 'bin/freeswitch' | head -1)"
echo "     ls -la /proc/\$FS_PID/fd/ | grep freeswitch.log"
echo "     （記下 fd 編號後）cat /proc/\$FS_PID/fdinfo/<編號>"
echo "     pos 應該從 0 開始重新累加，而不是停在舊數字不動；且 fd 建立時間應更新為現在"
echo "  4. 撥一通測試電話，幾秒後確認："
echo "     tail -5 /var/log/freeswitch/freeswitch.log        # 應該看得到剛剛的通話記錄"
echo "     tail -5 /var/log/freeswitch/cdr-csv/Master.csv     # 應該看得到剛剛這通的 CDR"
echo "  5. 確認沒有意外產生孤兒殘留檔："
echo "     ls -la /var/log/freeswitch/freeswitch.log.* 2>/dev/null"
echo "     ls -la /var/log/freeswitch/cdr-csv/Master.csv.* 2>/dev/null"
echo "     （應該不存在，或存在但已被自動清掉）"
echo "  6. 確認 push 前 git status 乾淨、git log 看到本次 fix: commit"
echo "  7. push/deploy.sh 由你自己手動執行"
echo "======================================================"
